1	"use strict";
2	// Nxeon Mod Builder build service.
3	//
4	// POST /builds                 {id, prompt, mcVersion, pluginName?, baseBuildId?, changeRequest?, tier?, images?} -> 202
5	//                              images (0.4+): [{name, type, data: base64}] up to 4 PNG/JPEG/WebP/GIF, 5 MB each.
6	//                              They are placed in the build workspace (reference/) for the model to Read.
7	// GET  /builds/:id             status + events + result
8	// GET  /builds/:id/artifact    the plugin .jar
9	// GET  /builds/:id/source?path=src/main/java/...   one source file (text). While the build runs (0.4+) this
10	//                              reads the LIVE workspace, src/main/** only, secret-scanned on the way out.
11	// GET  /builds/:id/live?draft=<path>&seq=<n>&from=<n>   (0.4+) live view while running: src/main/** file list
12	//                              (size + short hash) and the file the model is writing right now, streamed
13	//                              from the partial tool input (only the text after `from` when draft matches).
14	// GET  /builds/:id/source.zip  all source (+ Gradle template) as a zip
15	// POST /builds/:id/cancel
16	// GET  /health
17	//
18	// Every route except /health needs `Authorization: Bearer $MODBUILDER_API_KEY`.
19	// AI auth is whatever the Claude CLI finds in the environment:
20	//   CLAUDE_CODE_OAUTH_TOKEN (owner subscription, testing) or ANTHROPIC_API_KEY
21	//   (paid API, production). Swapping is a one-line change in the env file.
22	
23	const http = require("http");
24	const fs = require("fs");
25	const path = require("path");
26	const crypto = require("crypto");
27	const { spawn, execFileSync } = require("child_process");
28	const YAML = require("yaml");
29	const { scanBytecode, scanSource, scanSecrets } = require("./scan");
30	const P = require("./prompts");
31	const R = require("./route");
32	const { precheck, apiHints, warningCheck } = require("./precheck");
33	
34	const PORT = int(process.env.PORT, 3000);
35	const DATA = process.env.MB_DATA || "/data";
36	const BUILDS = path.join(DATA, "builds");
37	// Live workspaces sit outside /data so the model's Read-deny on //data/** keeps
38	// it away from other users' finished sources and the build records.
39	const WORK = process.env.MB_WORK || "/work";
40	const TEMPLATE = "/opt/mb/template";
41	const CP_DIR = "/opt/mb/classpath";
42	const API_KEY = process.env.MODBUILDER_API_KEY || "";
43	const MODEL = process.env.MB_MODEL || "sonnet";
44	const REPAIR_MODEL = process.env.MB_REPAIR_MODEL || MODEL;
45	const CONCURRENCY = int(process.env.MB_CONCURRENCY, 2);
46	const MAX_REPAIRS = int(process.env.MB_MAX_REPAIRS, 3);
47	const BUILD_BUDGET_USD = num(process.env.MB_BUILD_BUDGET_USD, 4);
48	const CALL_BUDGET_USD = num(process.env.MB_CALL_BUDGET_USD, 2.5);
49	const BUILD_TIMEOUT_MS = int(process.env.MB_BUILD_TIMEOUT_S, 1200) * 1000;
50	const CALL_TIMEOUT_MS = int(process.env.MB_CALL_TIMEOUT_S, 600) * 1000;
51	const MAX_TURNS = int(process.env.MB_MAX_TURNS, 60);
52	const VERSIONS = (process.env.MB_VERSIONS || "1.21.11").split(/\s+/).filter(Boolean);
53	const SECRETS = [process.env.CLAUDE_CODE_OAUTH_TOKEN, process.env.ANTHROPIC_API_KEY, API_KEY].filter(Boolean);
54	// Reference images (0.4+): what the owner pasted into the prompt, for the model to look at.
55	// Reference images + live code helpers (pure, unit-tested: test/modbuilder-live.test.ts).
56	const { MAX_REFS, MAX_REF_BYTES, REF_EXT, LIVE_PATH, parseImages, partialField, liveRel } = require("./live");
57	const LIVE_STREAM = process.env.MB_LIVE_STREAM !== "off";
58	
59	function int(v, d) { const n = parseInt(v || "", 10); return Number.isFinite(n) ? n : d; }
60	function num(v, d) { const n = parseFloat(v || ""); return Number.isFinite(n) ? n : d; }
61	function now() { return new Date().toISOString(); }
62	function log(level, msg, meta = {}) { process.stderr.write(JSON.stringify({ ts: now(), level, msg, ...meta }) + "\n"); }
63	
64	fs.mkdirSync(BUILDS, { recursive: true });
65	fs.mkdirSync(WORK, { recursive: true });
66	
67	// ---------------------------------------------------------------- state ----
68	const records = new Map(); // id -> record (also persisted to build.json)
69	const queue = [];
70	const running = new Map(); // id -> { child, cancelled }
71	
72	function dirOf(id) { return path.join(BUILDS, id); }
73	function save(rec) {
74	  rec.updatedAt = now();
75	  const f = path.join(dirOf(rec.id), "build.json");
76	  fs.writeFileSync(f + ".tmp", JSON.stringify(rec, null, 2));
77	  fs.renameSync(f + ".tmp", f);
78	}
79	function event(rec, stage, message, detail) {
80	  rec.events.push({ at: now(), stage, message, ...(detail ? { detail: String(detail).slice(0, 4000) } : {}) });
81	  if (rec.events.length > 400) rec.events.splice(1, rec.events.length - 400);
82	  save(rec);
83	}
84	function setStage(rec, status, message) { rec.status = status; event(rec, status, message); }
85	
86	// Load persisted builds; anything mid-flight when the service stopped is failed.
87	for (const id of fs.readdirSync(BUILDS)) {
88	  try {
89	    const rec = JSON.parse(fs.readFileSync(path.join(dirOf(id), "build.json"), "utf8"));
90	    if (!["succeeded", "failed"].includes(rec.status)) {
91	      rec.status = "failed";
92	      rec.error = "The build service restarted while this build was running. Please try again.";
93	      rec.errorCode = "interrupted";
94	      rec.finishedAt = now();
95	      rec.events.push({ at: now(), stage: "failed", message: "Interrupted by a service restart" });
96	      save(rec);
97	    }
98	    records.set(id, rec);
99	  } catch { /* ignore broken dirs */ }
100	}
101	
102	// ------------------------------------------------------------- helpers ----
103	function copyDir(src, dst, filter = () => true) {
104	  fs.mkdirSync(dst, { recursive: true });
105	  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
106	    const s = path.join(src, e.name), d = path.join(dst, e.name);
107	    if (!filter(s, e)) continue;
108	    if (e.isDirectory()) copyDir(s, d, filter);
109	    else if (e.isFile()) fs.copyFileSync(s, d);
110	  }
111	}
112	function listFiles(root, rel = "") {
113	  const out = [];
114	  const abs = path.join(root, rel);
115	  if (!fs.existsSync(abs)) return out;
116	  for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
117	    const r = path.posix.join(rel, e.name);
118	    if (e.isSymbolicLink()) { fs.rmSync(path.join(root, r), { force: true }); continue; }
119	    if (e.isDirectory()) out.push(...listFiles(root, r));
120	    else if (e.isFile()) out.push({ rel: r, abs: path.join(root, r), size: fs.statSync(path.join(root, r)).size });
121	  }
122	  return out;
123	}
124	function rmrf(p) { fs.rmSync(p, { recursive: true, force: true }); }
125	// Read-only listing for the live view (listFiles removes symlinks; this one only skips them).
126	function listFilesSafe(root, rel = "") {
127	  const out = [];
128	  const abs = path.join(root, rel);
129	  let entries;
130	  try { entries = fs.readdirSync(abs, { withFileTypes: true }); } catch { return out; }
131	  for (const e of entries) {
132	    const r = path.posix.join(rel, e.name);
133	    if (e.isSymbolicLink()) continue;
134	    if (e.isDirectory()) out.push(...listFilesSafe(root, r));
135	    else if (e.isFile()) { try { out.push({ rel: r, abs: path.join(root, r), size: fs.statSync(path.join(root, r)).size }); } catch { /* raced */ } }
136	  }
137	  return out;
138	}
139	
140	// The service-owned copy lives in the build dir (the model's Read-deny covers //data/**);
141	// a fresh copy goes into the workspace's reference/ folder only for the length of each AI call.
142	function refDir(id) { return path.join(dirOf(id), "reference"); }
143	function refFile(r) { return `${r.n}.${REF_EXT[r.type]}`; }
144	function placeRefs(rec, ws) {
145	  if (!rec.references || !rec.references.length) return;
146	  const dst = path.join(ws, "reference");
147	  rmrf(dst); fs.mkdirSync(dst, { recursive: true });
148	  for (const r of rec.references) fs.copyFileSync(path.join(refDir(rec.id), refFile(r)), path.join(dst, refFile(r)));
149	}
150	// Removed silently after every AI call, before sanitizeWorkspace: reference/ never reaches the
151	// compiler, the extracted source, the zip or the live view.
152	function dropRefs(ws) { rmrf(path.join(ws, "reference")); }
153	
154	function hasSecret(text) {
155	  if (/sk-ant-[A-Za-z0-9_-]{10,}/.test(text)) return true;
156	  return SECRETS.some((s) => s && s.length >= 16 && text.includes(s));
157	}
158	function childEnv(withAi) {
159	  const env = { PATH: process.env.PATH, HOME: process.env.HOME || "/home/claude", JAVA_HOME: process.env.JAVA_HOME, LANG: "C.UTF-8" };
160	  if (withAi) {
161	    for (const k of ["CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY", "ANTHROPIC_BASE_URL"]) if (process.env[k]) env[k] = process.env[k];
162	    env.DISABLE_AUTOUPDATER = "1";
163	    env.DISABLE_ERROR_REPORTING = "1";
164	    env.DISABLE_BUG_COMMAND = "1";
165	    // Live code (0.4+): CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC / DISABLE_TELEMETRY also switch off
166	    // the CLI's eager tool-input streaming (measured 2026-10-07: Write input then arrives in one burst
167	    // at the end instead of ~20 deltas/s). Egress stays limited by the container firewall to the
168	    // Anthropic API hosts either way. MB_LIVE_STREAM=off restores the 0.3 behaviour.
169	    if (!LIVE_STREAM) env.DISABLE_TELEMETRY = "1";
170	  }
171	  return env;
172	}
173	function run(cmd, args, opts) {
174	  return new Promise((resolve) => {
175	    const child = spawn(cmd, args, { cwd: opts.cwd, env: opts.env, stdio: ["ignore", "pipe", "pipe"] });
176	    if (opts.track) opts.track.child = child;
177	    let out = "", err = "";
178	    child.stdout.on("data", (d) => { out += d; if (opts.onStdout) opts.onStdout(d); if (out.length > 8e6) out = out.slice(-4e6); });
179	    child.stderr.on("data", (d) => { err += d; if (err.length > 2e6) err = err.slice(-1e6); });
180	    const t = setTimeout(() => { child.kill("SIGKILL"); err += "\n[timeout]"; }, opts.timeout);
181	    child.on("close", (code, signal) => { clearTimeout(t); resolve({ code, signal, out, err, timedOut: err.endsWith("[timeout]") }); });
182	    child.on("error", (e) => { clearTimeout(t); resolve({ code: -1, out, err: String(e) }); });
183	  });
184	}
185	
186	// ------------------------------------------------------------ AI calls ----
187	const SETTINGS = JSON.stringify({
188	  permissions: {
189	    deny: ["Bash", "WebFetch", "WebSearch", "Read(//proc/**)", "Read(//etc/**)", "Read(//home/**)", "Read(//opt/**)", "Read(//root/**)", "Read(//run/**)", "Read(//data/**)"],
190	  },
191	});
192	
193	async function callClaude(rec, ctl, ws, prompt, { resume, model, kind }) {
194	  const args = ["-p", "--output-format", "stream-json", "--verbose",
195	    "--permission-mode", "acceptEdits",
196	    "--tools", "Read", "Write", "Edit", "Glob", "Grep",
197	    "--settings", SETTINGS, "--strict-mcp-config",
198	    "--include-partial-messages",
199	    "--model", model, "--max-turns", String(MAX_TURNS),
200	    "--max-budget-usd", String(Math.max(0.2, Math.min(CALL_BUDGET_USD, BUILD_BUDGET_USD - rec.costUsd))),
201	    "--system-prompt", P.systemPrompt(rec.mcVersion)];
202	  if (resume) args.push("--resume", resume); else args.push("--session-id", rec.sessionId);
203	  args.push("--", prompt);
204	
205	  let buf = "", result = null, wroteAny = false, callModel = null;
206	  const onStdout = (d) => {
207	    buf += d;
208	    let i;
209	    while ((i = buf.indexOf("\n")) >= 0) {
210	      const line = buf.slice(0, i); buf = buf.slice(i + 1);
211	      if (!line.trim()) continue;
212	      let msg; try { msg = JSON.parse(line); } catch { continue; }
213	      if (msg.type === "stream_event" && msg.event) {
214	        // Live code: follow the Write/Edit tool input as the model generates it.
215	        const ev = msg.event;
216	        if (ev.type === "content_block_start" && ev.content_block && ev.content_block.type === "tool_use") {
217	          const name = ev.content_block.name;
218	          ctl.draft = (name === "Write" || name === "Edit" || name === "MultiEdit") ? { tool: name, json: "", idx: ev.index, at: Date.now(), seq: (ctl.draft ? ctl.draft.seq : 0) + 1 } : null;
219	        } else if (ev.type === "content_block_delta" && ev.delta && ev.delta.type === "input_json_delta" && ctl.draft && ctl.draft.idx === ev.index) {
220	          if (ctl.draft.json.length < 1.5 * 1024 * 1024) ctl.draft.json += ev.delta.partial_json || "";
221	          ctl.draft.at = Date.now();
222	        } else if (ev.type === "content_block_stop" && ctl.draft && ctl.draft.idx === ev.index) {
223	          ctl.draft.done = true;
224	        }
225	        continue;
226	      }
227	      if (msg.type === "assistant" && msg.message && Array.isArray(msg.message.content)) {
228	        for (const c of msg.message.content) {
229	          if (c.type !== "tool_use") continue;
230	          const fp = c.input && (c.input.file_path || c.input.path || "");
231	          const rel = fp ? path.relative(ws, fp) || fp : "";
232	          const short = rel.split("/").pop();
233	          if (c.name === "Write" || c.name === "Edit" || c.name === "MultiEdit") {
234	            if (!wroteAny && rec.status === "planning") setStage(rec, "coding", "Writing the plugin code");
235	            wroteAny = true;
236	            event(rec, rec.status, `${c.name === "Write" ? "Wrote" : "Edited"} ${short}`);
237	          } else if (c.name === "Read" && short) event(rec, rec.status, `Reading ${short}`);
238	        }
239	      } else if (msg.type === "user" && msg.message && Array.isArray(msg.message.content)) {
240	        // Rejected tool calls (e.g. a Write outside the workspace): internal diagnostics only.
241	        for (const c of msg.message.content) {
242	          if (c.type === "tool_result" && c.is_error) {
243	            const t = Array.isArray(c.content) ? c.content.map((x) => x.text || "").join(" ") : String(c.content || "");
244	            rec.toolErrors = [...(rec.toolErrors || []), t.slice(0, 200)].slice(-20);
245	          }
246	        }
247	      } else if (msg.type === "system" && msg.subtype === "init" && msg.model) {
248	        callModel = msg.model;
249	        if (!rec.resolvedModel) rec.resolvedModel = msg.model;
250	      } else if (msg.type === "result") result = msg;
251	    }
252	  };
253	  const r = await run("claude", args, { cwd: ws, env: childEnv(true), timeout: CALL_TIMEOUT_MS, onStdout, track: ctl });
254	  ctl.child = null;
255	  const cost = result && typeof result.total_cost_usd === "number" ? result.total_cost_usd : 0;
256	  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
257	  const u = (result && result.usage) || {};
258	  const callTokens = { input: (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0), cacheRead: u.cache_read_input_tokens || 0, output: u.output_tokens || 0 };
259	  rec.aiCalls.push({ at: now(), kind: kind || (resume ? "repair" : "generate"), route: rec.route ? rec.route.class : null, model, resolvedModel: callModel, costUsd: cost, tokens: callTokens, turns: result ? result.num_turns : null, durationMs: result ? result.duration_ms : null, subtype: result ? result.subtype : null, exit: r.code });
260	  rec.tokens.input += callTokens.input;
261	  rec.tokens.output += callTokens.output;
262	  save(rec);
263	  if (ctl.cancelled) throw fail("cancelled", "Build cancelled.");
264	  if (!result) {
265	    log("error", "claude produced no result", { id: rec.id, code: r.code, err: r.err.slice(-2000) });
266	    const authish = /auth|401|403|login|credit|quota|rate.?limit|overloaded/i.test(r.err);
267	    throw fail(r.timedOut ? "timeout" : "ai_unavailable", r.timedOut ? "The AI took too long on this one. Try a smaller request." : "The AI builder is unavailable right now. Please try again in a few minutes.", authish ? "AI service error" : r.err.slice(-1500));
268	  }
269	  if (result.subtype === "error_max_budget_usd") throw fail("budget", "This build reached its spending cap before finishing. Try a smaller request or split it into two plugins.");
270	  // The model provider's own safeguard blocked the request (seen with Sonnet 5.5 on
271	  // the backdoor / env-dump eval prompts): that is a refusal, not an outage.
272	  if (result.is_error && /safeguards flagged|\[cyber\]|usage polic/i.test(String(result.result || ""))) {
273	    throw fail("refused", "We can't build this one. It goes against our plugin safety rules.", String(result.result).slice(0, 300));
274	  }
275	  if (result.is_error && result.subtype !== "error_max_turns") {
276	    throw fail("ai_unavailable", "The AI builder hit an error. Please try again in a few minutes.", String(result.result || result.subtype).slice(0, 1500));
277	  }
278	  return result;
279	}
280	
281	// One very cheap Haiku call that answers simple|standard|complex (MB_CLASSIFIER=haiku).
282	async function classifyWithHaiku(rec, ctl, text) {
283	  const args = ["-p", "--output-format", "json", "--tools", "", "--strict-mcp-config", "--settings", SETTINGS,
284	    "--model", R.HAIKU, "--max-turns", "1", "--max-budget-usd", "0.05", "--system-prompt", R.CLASSIFIER_PROMPT, "--", `<request>\n${text}\n</request>`];
285	  const cwd = path.join(WORK, `${rec.id}-cls`);
286	  fs.mkdirSync(cwd, { recursive: true });
287	  const r = await run("claude", args, { cwd, env: childEnv(true), timeout: 60000, track: ctl });
288	  ctl.child = null;
289	  rmrf(cwd);
290	  let j = null; try { j = JSON.parse(r.out); } catch { /* fall through */ }
291	  const cost = j && typeof j.total_cost_usd === "number" ? j.total_cost_usd : 0;
292	  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
293	  rec.aiCalls.push({ at: now(), kind: "classify", route: null, model: R.HAIKU, resolvedModel: R.HAIKU, costUsd: cost, turns: j ? j.num_turns : null, durationMs: j ? j.duration_ms : null, subtype: j ? j.subtype : null, exit: r.code });
294	  const word = j && typeof j.result === "string" ? (j.result.toLowerCase().match(/simple|standard|complex/) || [null])[0] : null;
295	  return word;
296	}
297	
298	async function chooseRoute(rec, ctl) {
299	  if (rec.override) {
300	    // Customer picked the model (tier). No classifier call; repairs stay on it.
301	    const h = R.classifyHeuristic(rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt);
302	    const m = rec.override.model;
303	    const up = rec.override.tier ? R.TIERS[R.TIER_UP[rec.override.tier]] : m;
304	    return { ...h, heuristicClass: h.class, class: rec.override.tier || "override", method: "override", tier: rec.override.tier, models: { generate: m, repairCheap: null, escalate: up, escalateAfter: 2 } };
305	  }
306	  const base = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
307	  const h = R.classifyHeuristic(rec.prompt);
308	  let route = { ...h };
309	  if (rec.baseBuildId) {
310	    // A change request on an existing plugin: at least as hard as the change itself,
311	    // and the model must read the old code, so never below the original's class.
312	    const hc = R.classifyHeuristic(rec.changeRequest);
313	    route = { ...h, class: R.maxClass(h.class, hc.class), changeScore: hc.score };
314	  }
315	  const sameModel = new Set(Object.values(R.CFG.models)).size === 1;
316	  if (R.CFG.classifier === "haiku" && sameModel && R.CFG.routing) route = { ...route, method: "heuristic (all classes use one model, classifier skipped)" };
317	  else if (R.CFG.classifier === "haiku") {
318	    const word = await classifyWithHaiku(rec, ctl, base).catch(() => null);
319	    route = { ...route, heuristicClass: route.class, class: word || route.class, method: word ? "haiku" : "heuristic (haiku failed)" };
320	  }
321	  if (!R.CFG.routing) route = { ...route, routedClass: route.class, method: `${route.method}, routing off` };
322	  const gen = R.CFG.routing ? R.CFG.models[route.class] : MODEL;
323	  route.models = { generate: gen, repairCheap: R.CFG.routing && R.CFG.repairCheapFirst ? R.CFG.repairCheapModel : null, escalate: R.CFG.routing ? escalateFrom(gen) : REPAIR_MODEL };
324	  return route;
325	}
326	// The model a failed repair escalates to: one class up from the generation model.
327	function escalateFrom(model) {
328	  const m = R.CFG.models;
329	  if (model === m.simple) return m.standard;
330	  if (model === m.standard) return m.complex;
331	  return model;
332	}
333	
334	function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }
335	
336	// ------------------------------------------------------- validation/compile
337	function readSummary(ws) {
338	  const f = path.join(ws, "modbuilder.json");
339	  if (!fs.existsSync(f)) return null;
340	  try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return { _invalid: true }; }
341	}
342	
343	// Keep the model inside its lane: only src/main/** and modbuilder.json survive,
344	// Gradle files always come from the pinned template.
345	function sanitizeWorkspace(ws, rec) {
346	  for (const f of listFiles(ws)) {
347	    const ok = f.rel.startsWith("src/main/java/") || f.rel.startsWith("src/main/resources/") || f.rel === "modbuilder.json"
348	      || f.rel === "build.gradle.kts" || f.rel === "settings.gradle.kts";
349	    if (!ok) { fs.rmSync(f.abs, { force: true }); event(rec, rec.status, `Removed unexpected file ${f.rel}`); }
350	  }
351	  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
352	}
353	
354	function validate(ws, rec) {
355	  const problems = [];
356	  const res = path.join(ws, "src/main/resources");
357	  const ymlPath = path.join(res, "plugin.yml");
358	  if (fs.existsSync(path.join(res, "paper-plugin.yml"))) problems.push("Use plugin.yml, not paper-plugin.yml: delete src/main/resources/paper-plugin.yml.");
359	  if (!fs.existsSync(ymlPath)) return { problems: ["src/main/resources/plugin.yml is missing."], yml: null };
360	  let yml;
361	  try { yml = YAML.parse(fs.readFileSync(ymlPath, "utf8")); } catch (e) { return { problems: [`plugin.yml is not valid YAML: ${e.message}`], yml: null }; }
362	  if (!yml || typeof yml !== "object") return { problems: ["plugin.yml is empty."], yml: null };
363	  if (!/^[A-Za-z0-9_]{1,40}$/.test(String(yml.name || ""))) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
364	  if (!yml.version) problems.push("plugin.yml needs a version.");
365	  const main = String(yml.main || "");
366	  if (!/^[a-zA-Z_][\w]*(\.[a-zA-Z_][\w]*)+$/.test(main)) problems.push("plugin.yml main must be a fully-qualified class name.");
367	  else if (!fs.existsSync(path.join(ws, "src/main/java", main.replace(/\./g, "/") + ".java"))) problems.push(`plugin.yml main is ${main} but src/main/java/${main.replace(/\./g, "/")}.java does not exist.`);
