370	  // With '1.21' a 1.21.11 build also "loads" on a 1.21.1 server and then crashes
371	  // on API that version does not have (the Growth incident: Attribute.SCALE ->
372	  // InvalidPluginException initializing the main class). With '1.21.11' Paper
373	  // 1.21.1 refuses it cleanly ("Unsupported API version 1.21.11") while 1.21.11+
374	  // load it. Verified on real Paper 1.21.1 / 1.21.8 / 1.21.11 servers 2026-10-07.
375	  const apiVersion = rec.mcVersion;
376	  if (String(yml["api-version"] || "") !== apiVersion) {
377	    // Mechanical fix, not worth a model round-trip.
378	    yml["api-version"] = apiVersion;
379	    fs.writeFileSync(ymlPath, YAML.stringify(yml));
380	  }
381	  // getCommand("x") without a plugin.yml entry returns null at runtime -> NPE on enable.
382	  const declared = new Set(Object.keys((yml.commands && typeof yml.commands === "object") ? yml.commands : {}).map((s) => s.toLowerCase()));
