384	  if (!java.length) problems.push("No Java source files were written.");
385	  for (const f of java) {
386	    const text = fs.readFileSync(f.abs, "utf8");
387	    for (const m of text.matchAll(/getCommand\(\s*"([^"]+)"\s*\)/g)) {
388	      if (!declared.has(m[1].toLowerCase())) problems.push(`${f.rel} calls getCommand("${m[1]}") but plugin.yml has no command "${m[1]}" (it would crash on enable).`);
