392	  const total = listFiles(ws, "src").reduce((a, f) => a + f.size, 0);
393	  if (total > 1.5 * 1024 * 1024) problems.push("The source is too large (over 1.5 MB).");
394	  return { problems: [...new Set(problems)], yml };
