397	async function compile(ws, rec, ctl) {
398	  const out = path.join(ws, "build/classes");
399	  rmrf(path.join(ws, "build")); fs.mkdirSync(out, { recursive: true });
400	  const cp = fs.readFileSync(path.join(CP_DIR, `${rec.mcVersion}.txt`), "utf8").trim();
401	  const sources = listFiles(ws, "src/main/java").filter((f) => f.rel.endsWith(".java")).map((f) => f.abs);
402	  const r = await run("javac", ["-J-Xmx768m", "--release", "21", "-encoding", "UTF-8", "-proc:none", "-Xmaxerrs", "40", "-Xlint:deprecation,removal", "-cp", cp, "-d", out, ...sources],
403	    { cwd: ws, env: childEnv(false), timeout: 180000, track: ctl });
404	  ctl.child = null;
405	  const output = (r.err + r.out).split(ws + "/").join("");
406	  if (r.code !== 0) return { ok: false, errors: output.slice(0, 12000) };
407	  // Resources (plugin.yml, config.yml, ...)
408	  copyDir(path.join(ws, "src/main/resources"), out);
409	  const jar = path.join(ws, "build/plugin.jar");
410	  const j = await run("jar", ["--create", "--file", jar, "-C", out, "."], { cwd: ws, env: childEnv(false), timeout: 60000 });
411	  if (j.code !== 0) return { ok: false, errors: j.err.slice(0, 4000) };
412	  const warnings = (output.match(/warning: \[(deprecation|removal)\][^\n]*/g) || []).slice(0, 10);
413	  return { ok: true, jar, classes: out, warnings };
414	}
