// Each matching group adds its weight once. Weights reflect how much code and
// API surface a feature usually pulls in (and how often it broke in real builds).
const FEATURES = [
  ["gui", 2, /\b(gui|menus?|chest (menu|gui)|inventory (menu|gui)|clicking|click(s|ed)? (on )?(an?|the|one) )/],
  ["persist", 1, /\b(saved?|persist\w*|stored?|survive|between restarts|across restarts|to (a )?file|to disk|database)\b/],
  ["scoreboard", 2, /\b(scoreboard|sidebar|tab ?list|leaderboard|top \d+)\b/],
  ["bossbar", 1, /\bboss ?bar\b/],
  ["economy", 2, /\b(coins?|money|balance|economy|shop|buy|sell|prices?|pay)\b/],
  ["region", 2, /\b(regions?|zones?|claims?|claimed|arena|pos1|pos2|corners?|chunks?|hill)\b/],
  ["protection", 2, /\b(protect\w*|cannot break|can't break|grief\w*|trusted?|containers?|explosions?)\b/],
  ["minigame", 3, /\b(mini-?game|rounds?|points?|winner|wins|first to|teams?|lobby|king of the hill)\b/],
  ["boss", 2, /\b(boss(?! ?bar)|phases?|minions?|waves?)\b/],
  ["timer", 1, /\b(every (\d+ )?(seconds?|minutes?|hours?|day)|timer|countdown|cooldown|per second|each second|daily|midnight|streaks?)\b/],
  ["quests", 3, /\b(quests?|missions?|achievements?|objectives?)\b/],
  ["random", 1, /\brandom(ly)?\b/],
  ["effects", 1, /\b(potion|effects?|speed|strength|glowing|particles?|trails?|sounds?|titles?|fireworks?|lightning)\b/],
  ["items", 1, /\b(items?|recipes?|enchant\w*|lore|loot|drops?|rewards?|inventory)\b/],
  ["entities", 1, /\b(spawns?|mobs?|zombies?|skeletons?|entity|entities|npcs?)\b/],
  ["perms", 0.5, /\bpermission/],
  ["config", 0.5, /\bconfig/],
