#!/usr/bin/env python3
"""Where does the Mod Builder's AI spend go?  Read-only analysis of build records.

  python3 spend.py [--builds DIR] [--sessions DIR] [--prefix ev-v5-] [--ttl auto|5m|1h] [--top 10]

--builds    a directory of <id>/build.json (default /var/lib/modbuilder/data/builds on the
            build VM; or a read-only copy, e.g. `tar czf - */build.json` piped off the VM)
--sessions  optional: the Claude CLI's session transcripts (inside the container
            /home/claude/.claude/projects, `docker exec modbuilder tar czf - -C /home/claude/.claude projects`)
            gives per-turn usage for builds made before service 0.5 recorded it itself
--prefix    only build ids starting with this (e.g. ev-v5- for one eval run)
--ttl       cache-write price to model the cost with (5m = 1.25x input, 1h = 2x); auto picks the
            one that reproduces the CLI's own reported cost best

Never writes anything. Prices: services/modbuilder/usage.js PRICES (list prices, USD / MTok).
"""
import argparse, collections, glob, hashlib, json, os, re, statistics as st

PRICES = {"haiku": (1, 5), "sonnet-5-5": (2, 10), "sonnet-5": (2, 10), "opus-5-5": (4, 20), "opus-5": (5, 25)}


def price(model):
    m = str(model or "")
    for k in ("haiku", "opus-5-5", "opus-5", "sonnet-5-5", "sonnet-5"):
        if k in m:
            return PRICES[k]
    return PRICES["sonnet-5-5"]


def parts(tok, model, ttl):
    pin, pout = price(model)
    w = 1.25 if ttl == "5m" else 2.0
    unc = tok.get("uncached") or 0
    cw = tok.get("cacheWrite")
    if cw is None:
        cw = max(0, (tok.get("input") or 0) - (tok.get("cacheRead") or 0) - unc)
    return {
        "output": (tok.get("output") or 0) * pout / 1e6,
        "cacheWrite": cw * pin * w / 1e6,
        "cacheRead": (tok.get("cacheRead") or 0) * pin * 0.1 / 1e6,
        "uncached": unc * pin / 1e6,
    }


def short(m):
    return re.sub(r"^claude-|-\d{8}$", "", str(m or "?"))


def pct(a, b):
    return f"{100 * a / b:4.0f}%" if b else "   -"


def load_sessions(d):
    """session id -> list of turns [uncached, cacheWrite, cacheRead, output, tools]"""
    out = {}
    if not d:
        return out
    for f in glob.glob(os.path.join(d, "**", "*.jsonl"), recursive=True):
        sid = os.path.splitext(os.path.basename(f))[0]
        turns, order = {}, []
        for line in open(f, errors="replace"):
            try:
                m = json.loads(line)
            except Exception:
                continue
            if m.get("type") != "assistant":
                continue
            msg = m.get("message") or {}
            mid = msg.get("id") or len(order)
            if mid not in turns:
                turns[mid] = {"u": {}, "tools": []}
                order.append(mid)
            if msg.get("usage"):
                turns[mid]["u"] = msg["usage"]
            for c in msg.get("content") or []:
                if c.get("type") == "tool_use":
                    turns[mid]["tools"].append(c.get("name"))
        out[sid] = [[t["u"].get("input_tokens", 0), t["u"].get("cache_creation_input_tokens", 0), t["u"].get("cache_read_input_tokens", 0), t["u"].get("output_tokens", 0), ",".join(t["tools"])] for t in (turns[i] for i in order)]
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--builds", default="/var/lib/modbuilder/data/builds")
    ap.add_argument("--sessions", default="")
    ap.add_argument("--prefix", default="")
    ap.add_argument("--ttl", default="auto", choices=["auto", "5m", "1h"])
    ap.add_argument("--top", type=int, default=10)
    a = ap.parse_args()

    recs = []
    for f in glob.glob(os.path.join(a.builds, "*", "build.json")):
        try:
            r = json.load(open(f))
        except Exception:
            continue
        if a.prefix and not r.get("id", "").startswith(a.prefix):
            continue
        recs.append(r)
    if not recs:
        print("no build records found in", a.builds)
        return
    sess = load_sessions(a.sessions)
    calls = [(r, c) for r in recs for c in r.get("aiCalls") or []]
    total = sum(r.get("costUsd") or 0 for r in recs)
    costs = [r.get("costUsd") or 0 for r in recs]
    print(f"== {len(recs)} builds, {len(calls)} AI calls, reported spend ${total:.2f} (avg ${st.mean(costs):.3f}, median ${st.median(costs):.3f})")
    print("   status:", dict(collections.Counter(r.get("status") for r in recs)))
    print("   prompt versions:", dict(collections.Counter(r.get("promptVersion") for r in recs)))

    # ---- by kind x model
    print("\n== spend by call kind and model (reported cost)")
    g = collections.defaultdict(list)
    for r, c in calls:
        g[(c.get("kind") or "generate(<0.3)", short(c.get("resolvedModel") or c.get("model")))].append(c)
    print(f"   {'kind':16} {'model':14} {'calls':>5} {'$ total':>8} {'share':>5} {'$ avg':>7} {'turns':>5}")
    for k, v in sorted(g.items(), key=lambda kv: -sum(c.get("costUsd") or 0 for c in kv[1])):
        s = sum(c.get("costUsd") or 0 for c in v)
        print(f"   {k[0]:16} {k[1]:14} {len(v):5} {s:8.2f} {pct(s, total)} {s / len(v):7.3f} {st.mean([c.get('turns') or 0 for c in v]):5.1f}")

    # ---- decomposition (needs token records: service >= 0.3)
    tc = [(r, c) for r, c in calls if c.get("tokens") and c.get("kind") != "classify"]
    if tc:
        rep = sum(c.get("costUsd") or 0 for _, c in tc)
        fits = {}
        for ttl in ("5m", "1h"):
            fits[ttl] = sum(sum(parts(c["tokens"], c.get("resolvedModel") or c.get("model"), ttl).values()) for _, c in tc)
        ttl = a.ttl if a.ttl != "auto" else min(fits, key=lambda t: abs(fits[t] - rep))
        agg = collections.Counter()
        for _, c in tc:
            for k, v in parts(c["tokens"], c.get("resolvedModel") or c.get("model"), ttl).items():
                agg[k] += v
        mod = sum(agg.values())
        print(f"\n== where the money goes ({len(tc)} calls with token records; cache writes priced at {ttl} TTL)")
        print(f"   reported ${rep:.2f}; modelled 5m ${fits['5m']:.2f} / 1h ${fits['1h']:.2f}  -> the CLI is writing the cache with the {ttl} TTL" if a.ttl == "auto" else f"   reported ${rep:.2f}; modelled ${mod:.2f}")
        for k in ("output", "cacheWrite", "cacheRead", "uncached"):
            print(f"   {k:11} ${agg[k]:7.2f} {pct(agg[k], mod)}")
        tk = collections.Counter()
        for _, c in tc:
            t = c["tokens"]
            tk["output"] += t.get("output") or 0
            tk["cacheRead"] += t.get("cacheRead") or 0
            tk["write+uncached"] += max(0, (t.get("input") or 0) - (t.get("cacheRead") or 0))
        print("   tokens:", {k: f"{v / len(tc):,.0f}/call" for k, v in tk.items()})

        # thinking share: fresh one-call successes, output vs what landed in files
        rows = collections.defaultdict(list)
        for r in recs:
            if r.get("baseBuildId") or r.get("status") != "succeeded" or r.get("repairs"):
                continue
            gen = [c for c in r.get("aiCalls") or [] if c.get("kind") == "generate" and c.get("tokens")]
            if len(gen) != 1:
                continue
            c = gen[0]
            vis = sum(f.get("size", 0) for f in r.get("files") or [] if f.get("path", "").startswith("src/main") or f.get("path") == "modbuilder.json") / 3.0
            rows[(short(c.get("resolvedModel") or c.get("model")), r.get("tier") or "auto")].append((c["tokens"].get("output") or 0, vis, c.get("turns") or 0))
        if rows:
            print("\n== output tokens: code that landed in files vs the rest (mostly thinking; ~3 chars/token)")
            for k, v in sorted(rows.items()):
                o = st.mean(x[0] for x in v); vis = st.mean(x[1] for x in v)
                print(f"   {k[0]:14} {k[1]:6} n={len(v):3}  output {o:7,.0f}  in files ~{vis:6,.0f}  other ~{max(0, o - vis):6,.0f} ({pct(max(0, o - vis), o)})  turns {st.mean(x[2] for x in v):.1f}")

    # ---- turns: exploration and batching (0.5 records, or the CLI transcripts)
    explore = batch = n = 0
    for r, c in calls:
        rows = c.get("turnsDetail") or (sess.get(r.get("sessionId")) if c.get("kind") in ("generate", "change") else None)
        if not rows or c.get("kind") not in ("generate", "change"):
            continue
        n += 1
        tools0 = str(rows[0][-1]).split(",") if rows[0][-1] else []
        if tools0 and all(t in ("Glob", "Grep", "Read", "LS") for t in tools0) and not r.get("references") and not r.get("baseBuildId"):
            explore += 1
        writes = [len([t for t in str(x[-1]).split(",") if t in ("Write", "Edit")]) for x in rows]
        wt = [w for w in writes if w]
        batch += (sum(wt) / len(wt)) if wt else 0
    if n:
        print(f"\n== turns ({n} generate/change calls with per-turn data)")
        print(f"   fresh builds whose first turn only looked around (Glob/Read, nothing to find): {explore}/{n}")
        print(f"   files written per writing turn: {batch / n:.2f} (higher = fewer turns re-reading the context)")

    # ---- repairs
    rep_calls = [(r, c) for r, c in calls if str(c.get("kind") or "").startswith("repair")]
    old_rep = [r for r in recs if r.get("repairs") and not rep_calls]
    rs = sum(c.get("costUsd") or 0 for _, c in rep_calls)
    print(f"\n== repairs: {sum(1 for r in recs if r.get('repairs'))} builds needed one; repair calls ${rs:.2f} ({pct(rs, total)} of spend)")
    causes = collections.Counter()
    for r in recs:
        if not r.get("repairs"):
            continue
        for e in r.get("events") or []:
            if e.get("message") == "Error details":
                d = e.get("detail", "")
                if re.search(r"main class must not be final", d): causes["main class final (autofix 0.5)"] += 1
                elif re.search(r"symbol:\s+variable (GENERIC_|PLAYER_)?[A-Z_]+\n\s+location: (class|interface) Attribute", d): causes["Attribute name prefix (autofix 0.5)"] += 1
                elif re.search(r"^import [\w.]+;\n\s*\^\n\s+symbol:\s+class", d, re.M): causes["import from wrong package (autofix 0.5)"] += 1
                elif "plugin.yml is missing" in d: causes["files written outside the workspace (prompt fix 0.3)"] += 1
                else: causes["other: " + (re.search(r"error: ([^\n]{0,70})", d) or [None, d[:70].replace(chr(10), ' ')])[1]] += 1
                break
    for k, v in causes.most_common():
        print(f"   {v:3}  {k}")
    af = [r for r in recs if (r.get("usage") or {}).get("autofix")]
    if af:
        print(f"   0.5 autofix: {sum(r['usage']['autofix'] for r in af)} lines fixed in {len(af)} builds, model repairs saved: {sum(r['usage'].get('savedRepairs', 0) for r in af)}")

    # ---- exact repeats (what MB_DEDUPE=on would have saved)
    keys = collections.defaultdict(list)
    for r in recs:
        if r.get("baseBuildId") or r.get("references"):
            continue
        k = r.get("dedupeKey") or hashlib.sha256(json.dumps([r.get("promptVersion"), r.get("knowledge"), r.get("mcVersion"), r.get("pluginName") or "", r.get("tier") or "auto", re.sub(r"\s+", " ", r.get("prompt", "")).strip()]).encode()).hexdigest()
        keys[k].append(r)
    rep_n = rep_usd = 0
    for v in keys.values():
        v.sort(key=lambda r: r.get("createdAt", ""))
        ok = [i for i, r in enumerate(v) if r.get("status") == "succeeded"]
        if ok:
            later = v[ok[0] + 1:]
            rep_n += len(later)
            rep_usd += sum(r.get("costUsd") or 0 for r in later)
    print(f"\n== exact repeats after a success (MB_DEDUPE=on would reuse them): {rep_n} builds, ${rep_usd:.2f} ({pct(rep_usd, total)})")

    # ---- stage wall time (0.5 records)
    stg = collections.defaultdict(lambda: [0, 0])
    for r in recs:
        for k, v in ((r.get("usage") or {}).get("stages") or {}).items():
            stg[k][0] += v.get("n", 0); stg[k][1] += v.get("ms", 0)
    if stg:
        print("\n== wall time by stage (0.5 records)")
        for k, (cnt, ms) in sorted(stg.items(), key=lambda kv: -kv[1][1]):
            print(f"   {k:14} {cnt:5}x  {ms / 1000:8.1f} s total  {ms / max(1, cnt) / 1000:6.1f} s avg")

    print(f"\n== {a.top} most expensive builds")
    for r in sorted(recs, key=lambda r: -(r.get("costUsd") or 0))[: a.top]:
        cs = r.get("aiCalls") or []
        print(f"   ${r.get('costUsd', 0):.3f} {r.get('id', '')[:28]:28} {r.get('tier') or (r.get('route') or {}).get('class') or '':8} {r.get('status'):9} calls={len(cs)} turns={sum(c.get('turns') or 0 for c in cs)} {r.get('pluginName') or ''}")


