// Mod Builder service 0.5 (efficiency): usage metering, cost model, deterministic auto-fixes,
// exact-repeat keys and the prompt changes. Pure: no AI call, no javac, no network.
// The javac texts below are copied from real failed builds on the build service (2026-10-06/07).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const U = require("../services/modbuilder/usage.js") as any;
const AF = require("../services/modbuilder/autofix.js") as any;
const P = require("../services/modbuilder/prompts.js") as any;

function ws(files: Record<string, string>) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), "mb-eff-"));
  for (const [rel, text] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true });
    fs.writeFileSync(path.join(d, rel), text);
  }
  return d;
}
const read = (d: string, rel: string) => fs.readFileSync(path.join(d, rel), "utf8");

// A stand-in for the class index + javap of the real Paper jars (only what the tests touch).
const IDX: Record<string, Record<string, string[]>> = {
  "1.21.11": {
    FileConfiguration: ["org.bukkit.configuration.file.FileConfiguration"],
    NamespacedKey: ["org.bukkit.NamespacedKey"],
    Attribute: ["org.bukkit.attribute.Attribute"],
    NumberFormat: ["io.papermc.paper.scoreboard.numbers.NumberFormat"],
    Optional: ["com.google.common.base.Optional"],
    Ambig: ["org.bukkit.a.Ambig", "io.papermc.b.Ambig"],
  },
  "1.21.1": { Attribute: ["org.bukkit.attribute.Attribute"] },
};
const FIELDS: Record<string, string[]> = {
  "1.21.11|org.bukkit.attribute.Attribute": ["MAX_HEALTH", "SCALE", "MOVEMENT_SPEED", "JUMP_STRENGTH", "BLOCK_INTERACTION_RANGE"],
  "1.21.1|org.bukkit.attribute.Attribute": ["GENERIC_MAX_HEALTH", "GENERIC_SCALE", "GENERIC_MOVEMENT_SPEED", "PLAYER_BLOCK_INTERACTION_RANGE"],
};
const deps = {
  classIndex: (v: string) => new Map(Object.entries(IDX[v] || {})),
  members: (v: string, fqn: string) => (FIELDS[`${v}|${fqn}`] ? { fields: FIELDS[`${v}|${fqn}`], methods: [] } : null),
};

describe("usage meter", () => {
  const usage = (i: number, cw: number, cr: number, o: number) => ({ input_tokens: i, cache_creation_input_tokens: cw, cache_read_input_tokens: cr, output_tokens: o });
  it("counts one turn per API message id and each tool call once, whatever the block repeats", () => {
    const m = U.newMeter();
    // the CLI emits one assistant line per content block, all with the same id + usage
    U.onMessage(m, { type: "assistant", message: { id: "a", usage: usage(2, 560, 14818, 78), content: [{ type: "thinking" }] } });
    U.onMessage(m, { type: "assistant", message: { id: "a", usage: usage(2, 560, 14818, 78), content: [{ type: "tool_use", id: "t1", name: "Glob" }] } });
    U.onMessage(m, { type: "assistant", message: { id: "b", usage: usage(2, 189, 15378, 31455), content: [{ type: "tool_use", id: "t2", name: "Write" }] } });
    U.onMessage(m, { type: "assistant", message: { id: "b", usage: usage(2, 189, 15378, 31455), content: [{ type: "tool_use", id: "t2", name: "Write" }, { type: "tool_use", id: "t3", name: "Write" }] } });
    U.onMessage(m, { type: "stream_event", event: {} });
    const s = U.summarize(m);
    assert.equal(s.turnsDetail.length, 2);
    assert.deepEqual(s.turnsDetail[0], [2, 560, 14818, 78, 1, "Glob"]);
    assert.deepEqual(s.turnsDetail[1], [2, 189, 15378, 31455, 2, "Write,Write"]);
    assert.deepEqual(s.toolCalls, { Glob: 1, Write: 2 });
    assert.equal(s.explore, true, "a first turn that only globbed is exploration");
    // no result line: totals come from the turns
    assert.deepEqual(s.tokens, { input: 4 + 749 + 30196, cacheRead: 30196, output: 31533, uncached: 4, cacheWrite: 749 });
  });
  it("prefers the result's cumulative usage and keeps the old token fields' meaning", () => {
    const m = U.newMeter();
    U.onMessage(m, { type: "assistant", message: { id: "a", usage: usage(1, 1, 1, 1), content: [{ type: "tool_use", id: "x", name: "Write" }] } });
    U.onMessage(m, { type: "result", usage: usage(12, 46357, 205584, 44822), duration_api_ms: 1234 });
    const s = U.summarize(m);
    assert.equal(s.tokens.input, 12 + 46357 + 205584); // input = everything sent, as in 0.3/0.4
    assert.equal(s.tokens.cacheRead, 205584);
    assert.equal(s.tokens.cacheWrite, 46357);
    assert.equal(s.apiMs, 1234);
    assert.equal(s.explore, false);
  });
  it("adds calls and timed stages into rec.usage", () => {
    const rec: any = {};
    U.addCall(rec, { kind: "generate", costUsd: 0.1, durationMs: 1000, turns: 5, tokens: { input: 10, cacheWrite: 3, cacheRead: 6, output: 4 }, toolCalls: { Write: 3 } });
    U.addCall(rec, { kind: "generate", costUsd: 0.05, durationMs: 500, turns: 2, tokens: { input: 1, cacheWrite: 1, cacheRead: 0, output: 1 }, toolCalls: { Write: 1, Read: 1 } });
    U.addTime(rec, "compile", 3200.4);
    assert.deepEqual(rec.usage.stages.generate, { n: 2, ms: 1500, costUsd: 0.15, turns: 7, input: 11, cacheWrite: 4, cacheRead: 6, output: 5, toolCalls: { Write: 4, Read: 1 } });
    assert.deepEqual(rec.usage.stages.compile, { n: 1, ms: 3200 });
  });
});

describe("cost model", () => {
  it("reproduces a real build's reported cost with the 1 h cache-write price", () => {
    // build mb06c8f56cc7e6c71195cf (Saka = Sonnet 5): CLI reported $0.6760
    const t = { uncached: 12, cacheWrite: 46357, cacheRead: 205584, output: 44822 };
    const h = U.costParts(t, "claude-sonnet-5", "1h");
    assert.ok(Math.abs(h.total - 0.676) < 0.005, `1h model ${h.total}`);
    const m = U.costParts(t, "claude-sonnet-5", "5m");
    assert.ok(m.total < h.total - 0.03, "5 min TTL writes are cheaper");
    assert.ok(h.output / h.total > 0.6, "output (code + thinking) is most of it");
  });
  it("knows the model prices", () => {
    assert.deepEqual(U.priceOf("claude-haiku-4-5-20251001"), { in: 1, out: 5 });
    assert.deepEqual(U.priceOf("claude-opus-5-5"), { in: 4, out: 20 });
    assert.deepEqual(U.priceOf("claude-opus-5"), { in: 5, out: 25 });
    assert.deepEqual(U.priceOf("sonnet"), { in: 2, out: 10 });
  });
});

