describe("autofix: javac errors", () => {
  it("moves an import to the package the class really lives in (real error, p0-econ01)", () => {
    const rel = "src/main/java/dev/nxeon/plugins/simpleeconomy/gui/ShopGUI.java";
    const lines = Array.from({ length: 40 }, (_, i) => `// ${i + 1}`);
    lines[0] = "package dev.nxeon.plugins.simpleeconomy.gui;";
    lines[7] = "import org.bukkit.configuration.FileConfiguration;";
    lines[35] = "        FileConfiguration config = plugin.getConfig();";
    const d = ws({ [rel]: lines.join("\n") });
    const out = `${rel}:8: error: cannot find symbol
import org.bukkit.configuration.FileConfiguration;
                               ^
  symbol:   class FileConfiguration
  location: package org.bukkit.configuration
${rel}:36: error: cannot find symbol
        FileConfiguration config = plugin.getConfig();
        ^
  symbol:   class FileConfiguration
  location: class ShopGUI
2 errors
`;
    const r = AF.fixCompile(out, d, "1.21.11", deps);
    assert.equal(r.fixes.length, 1);
    assert.equal(r.fixes[0].kind, "wrong-import");
    const t = read(d, rel).split("\n");
    assert.equal(t[7], "import org.bukkit.configuration.file.FileConfiguration;");
    assert.equal(t.filter((l) => /^import /.test(l)).length, 1, "no duplicate import for the usage error");
  });
  it("renames prefixed Attribute constants on 1.21.11 (real error, Growth)", () => {
    const rel = "src/main/java/dev/nxeon/plugins/growth/GrowthPlugin.java";
    const lines = Array.from({ length: 130 }, () => "");
    lines[0] = "package dev.nxeon.plugins.growth;";
    lines[1] = "import org.bukkit.attribute.Attribute;";
    lines[109] = "        AttributeInstance scaleAttribute = player.getAttribute(Attribute.GENERIC_SCALE);";
    lines[115] = "        applyModifier(player, Attribute.GENERIC_MOVEMENT_SPEED, speedModifierKey,";
    lines[119] = "        applyModifier(player, Attribute.GENERIC_KNOCKBACK_RESISTANCE, k,";
    const d = ws({ [rel]: lines.join("\n") });
    const out = `${rel}:110: error: cannot find symbol
        AttributeInstance scaleAttribute = player.getAttribute(Attribute.GENERIC_SCALE);
                                                                        ^
  symbol:   variable GENERIC_SCALE
  location: interface Attribute
${rel}:116: error: cannot find symbol
        applyModifier(player, Attribute.GENERIC_MOVEMENT_SPEED, speedModifierKey,
                                       ^
  symbol:   variable GENERIC_MOVEMENT_SPEED
  location: interface Attribute
${rel}:120: error: cannot find symbol
        applyModifier(player, Attribute.GENERIC_KNOCKBACK_RESISTANCE, k,
                                       ^
  symbol:   variable GENERIC_KNOCKBACK_RESISTANCE
  location: interface Attribute
3 errors
`;
    const r = AF.fixCompile(out, d, "1.21.11", deps);
    const t = read(d, rel).split("\n");
    assert.match(t[109], /Attribute\.SCALE\)/);
    assert.match(t[115], /Attribute\.MOVEMENT_SPEED,/);
    assert.match(t[119], /GENERIC_KNOCKBACK_RESISTANCE/, "no such field in this (test) jar: left to the model");
    assert.equal(r.fixes.length, 2);
  });
  it("adds the 1.21.1 prefix, PLAYER_ included (real error, GraveBoss)", () => {
    const rel = "src/main/java/dev/nxeon/plugins/graveboss/BossManager.java";
    const d = ws({ [rel]: "package x;\nimport org.bukkit.attribute.Attribute;\n  a(Attribute.MAX_HEALTH); b(Attribute.MAX_HEALTH);\n  c(Attribute.BLOCK_INTERACTION_RANGE);\n" });
    const out = `${rel}:3: error: cannot find symbol
  a(Attribute.MAX_HEALTH); b(Attribute.MAX_HEALTH);
              ^
  symbol:   variable MAX_HEALTH
  location: class Attribute
${rel}:4: error: cannot find symbol
  c(Attribute.BLOCK_INTERACTION_RANGE);
              ^
  symbol:   variable BLOCK_INTERACTION_RANGE
  location: class Attribute
2 errors
`;
    AF.fixCompile(out, d, "1.21.1", deps);
    const t = read(d, rel).split("\n");
    assert.equal(t[2], "  a(Attribute.GENERIC_MAX_HEALTH); b(Attribute.GENERIC_MAX_HEALTH);");
    assert.equal(t[3], "  c(Attribute.PLAYER_BLOCK_INTERACTION_RANGE);");
  });
  it("adds a missing API import, but never guesses for JDK-like or ambiguous names", () => {
    const rel = "src/main/java/a/Main.java";
    const d = ws({ [rel]: "package a;\n\nimport org.bukkit.plugin.java.JavaPlugin;\n\npublic class Main extends JavaPlugin {\n  NamespacedKey k; Optional<String> o; Ambig z;\n}\n" });
    const block = (sym: string) => `${rel}:6: error: cannot find symbol
  NamespacedKey k; Optional<String> o; Ambig z;
  ^
  symbol:   class ${sym}
  location: class Main
`;
    const r = AF.fixCompile(block("NamespacedKey") + block("Optional") + block("Ambig"), d, "1.21.11", deps);
    assert.deepEqual(r.fixes.map((f: any) => f.to), ["import org.bukkit.NamespacedKey;"]);
    const t = read(d, rel).split("\n");
    assert.equal(t[3], "import org.bukkit.NamespacedKey;", "inserted after the last import");
  });
  it("ignores paths outside src/main/java and does nothing on unrelated errors", () => {
    const d = ws({ "src/main/java/a/A.java": "package a;\nclass A { void f() { int x = \"s\"; } }\n" });
    const r = AF.fixCompile(`src/main/java/a/A.java:2: error: incompatible types: String cannot be converted to int
class A { void f() { int x = "s"; } }
                             ^
../../etc/x.java:1: error: cannot find symbol
import org.bukkit.configuration.FileConfiguration;
^
  symbol:   class FileConfiguration
  location: package org.bukkit.configuration
`, d, "1.21.11", deps);
    assert.equal(r.fixes.length, 0);
  });
  it("tells the model what was changed when a repair still follows", () => {
    const note = AF.fixNote([{ file: "src/main/java/a/A.java", line: 3, from: "Attribute.GENERIC_SCALE", to: "Attribute.SCALE" }]);
    assert.match(note, /corrected these lines automatically/);
    assert.match(note, /A\.java:3: Attribute\.GENERIC_SCALE -> Attribute\.SCALE/);
    assert.equal(AF.fixNote([]), "");
    assert.match(P.repairPrompt("compile", "x.java:1: error", "/work/b", note), /^The build service already corrected/);
  });
});

describe("exact-repeat key", () => {
  const base = { promptVersion: "v", knowledge: "k", mcVersion: "1.21.11", pluginName: "", tier: "auto", model: "", prompt: "Make /heal  heal me", extra: [true, null] };
  it("ignores whitespace only", () => {
    assert.equal(U.dedupeKey(base), U.dedupeKey({ ...base, prompt: "  Make /heal heal me\n" }));
    assert.notEqual(U.dedupeKey(base), U.dedupeKey({ ...base, prompt: "make /heal heal me" }));
  });
  it("changes with version, tier, plugin name, prompt or knowledge version", () => {
    for (const k of ["mcVersion", "tier", "pluginName", "promptVersion", "knowledge"]) {
      assert.notEqual(U.dedupeKey(base), U.dedupeKey({ ...base, [k]: "other" }), k);
    }
  });
});

describe("prompts 0.5", () => {
  it("keeps the system prompt byte-identical per version (cache prefix) and bumps the version", () => {
    assert.equal(P.systemPrompt("1.21.11"), P.systemPrompt("1.21.11"));
    assert.equal(P.PROMPT_VERSION, "mb-2026-10-08.1");
    assert.match(P.systemPrompt("1.21.11"), /never one file per response/);
  });
  it("tells a fresh build there is nothing to look at, and keeps the request last", () => {
    const t = P.initialPrompt({ prompt: "heal command", mcVersion: "1.21.11", pluginName: "" }, "/work/abc", []);
    assert.match(t, /only build\.gradle\.kts and settings\.gradle\.kts/);
    assert.ok(t.trimEnd().endsWith("</request>"));
  });
});

