// Mod Builder service 0.5: the real server.js pipeline, offline. The Claude CLI, javac, jar and
// javap are replaced by tiny fake programs, so this spends nothing and needs no JDK. It checks
// the orchestration around the model: usage metering, the lean tool set, the deterministic
// auto-fixes (no model repair for a wrong import + a final main class), exact-repeat reuse and
// the `fresh` opt-out.
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const KEY = "test-key-0123456789abcdef";

const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
const ti = a.indexOf("--tools"); const tools = [];
for (let i = ti + 1; ti >= 0 && i < a.length && !a[i].startsWith("--"); i++) tools.push(a[i]);
fs.appendFileSync(process.env.FAKE_LOG, JSON.stringify({ tools, maxTurns: a[a.indexOf("--max-turns") + 1], effort: a.includes("--effort") ? a[a.indexOf("--effort") + 1] : null, kind: /Build this Paper/.test(prompt) ? "generate" : /change request/.test(prompt) ? "change" : "repair" }) + "\\n");
const ws = process.cwd();
const w = (rel, t) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); };
const out = (o) => process.stdout.write(JSON.stringify(o) + "\\n");
out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
const u1 = { input_tokens: 2, cache_creation_input_tokens: 900, cache_read_input_tokens: 14000, output_tokens: 3000 };
const u2 = { input_tokens: 2, cache_creation_input_tokens: 3100, cache_read_input_tokens: 14900, output_tokens: 40 };
if (/Build this Paper/.test(prompt)) {
  w("src/main/resources/plugin.yml", "name: Hello\\nversion: 1.0.0\\nmain: dev.nxeon.plugins.hello.Hello\\napi-version: '1.21'\\ndescription: hi\\nauthor: Nxeon Mod Builder\\n");
  w("src/main/java/dev/nxeon/plugins/hello/Hello.java", "package dev.nxeon.plugins.hello;\\n\\nimport org.bukkit.configuration.FileConfiguration;\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic final class Hello extends JavaPlugin {\\n  @Override public void onEnable() { FileConfiguration c = getConfig(); }\\n}\\n");
  w("modbuilder.json", JSON.stringify({ name: "Hello", version: "1.0.0", tagline: "Says hi", summary: "Says hi.", howToUse: ["Install it"] }));
} else if (/change request/.test(prompt)) {
  w("modbuilder.json", JSON.stringify({ name: "Hello", version: "1.1.0", tagline: "Says hi", summary: "Says hi.", changes: "More hi." }));
}
out({ type: "assistant", message: { id: "m1", usage: u1, content: [{ type: "thinking", thinking: "" }] } });
out({ type: "assistant", message: { id: "m1", usage: u1, content: [{ type: "tool_use", id: "t1", name: "Write", input: { file_path: ws + "/src/main/resources/plugin.yml" } }] } });
out({ type: "assistant", message: { id: "m1", usage: u1, content: [{ type: "tool_use", id: "t2", name: "Write", input: { file_path: ws + "/src/main/java/dev/nxeon/plugins/hello/Hello.java" } }] } });
out({ type: "assistant", message: { id: "m1", usage: u1, content: [{ type: "tool_use", id: "t3", name: "Write", input: { file_path: ws + "/modbuilder.json" } }] } });
out({ type: "assistant", message: { id: "m2", usage: u2, content: [{ type: "text", text: "Done." }] } });
out({ type: "result", subtype: "success", is_error: false, num_turns: 3, total_cost_usd: 0.05, duration_ms: 1200, duration_api_ms: 1100, result: "Done.",
  usage: { input_tokens: 4, cache_creation_input_tokens: 4000, cache_read_input_tokens: 28900, output_tokens: 3040 } });
`;
const FAKE_JAVAC = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const d = a[a.indexOf("-d") + 1];
const srcs = a.filter((x) => x.endsWith(".java"));
let errs = "";
for (const f of srcs) {
  fs.readFileSync(f, "utf8").split("\\n").forEach((l, i) => {
    if (l.trim() === "import org.bukkit.configuration.FileConfiguration;") errs += f + ":" + (i + 1) + ": error: cannot find symbol\\n" + l + "\\n                               ^\\n  symbol:   class FileConfiguration\\n  location: package org.bukkit.configuration\\n";
  });
}
if (errs) { process.stderr.write(errs + "1 error\\n"); process.exit(1); }
fs.mkdirSync(path.join(d, "dev/nxeon/plugins/hello"), { recursive: true });
fs.writeFileSync(path.join(d, "dev/nxeon/plugins/hello/Hello.class"), "x");
`;
const FAKE_JAR = `#!/usr/bin/env node
const a = process.argv.slice(2); require("fs").writeFileSync(a[a.indexOf("--file") + 1], "PK fake");
`;
const FAKE_JAVAP = `#!/usr/bin/env node
`;

let dir = "", proc: ChildProcess | null = null, port = 0;
const log = () => fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l));
async function api(method: string, p: string, body?: unknown) {
  const r = await fetch(`http://127.0.0.1:${port}${p}`, { method, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
  return r.json();
}
async function waitDone(id: string) {
  for (let i = 0; i < 200; i++) {
    const r = await api("GET", `/builds/${id}`);
    if (r.status === "succeeded" || r.status === "failed") return r;
    await new Promise((res) => setTimeout(res, 100));
  }
  throw new Error("build did not finish");
}

describe("modbuilder 0.5 pipeline (offline, fake CLI + javac)", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-pipe-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", FAKE_JAVAP]]) {
      fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    }
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/configuration/file/FileConfiguration.class\norg/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    port = 37000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_DEDUPE: "on",
        MB_EFFORT: "medium", FAKE_LOG: path.join(dir, "claude.log"),
      },
      stdio: ["ignore", "ignore", "pipe"],
    });
    let err = "";
    proc.stderr!.on("data", (d) => { err += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${err.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("reports 0.5 and its knobs on /health", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.equal(h.image, "0.5");
    assert.equal(h.features.usage, true);
    assert.equal(h.features.autofix, true);
    assert.equal(h.features.dedupe, true);
    assert.equal(h.features.effort, "medium");
  });

  it("builds with one AI call: wrong import + final main fixed without a model repair, usage recorded", async () => {
    await api("POST", "/builds", { id: "pipe-one-01", prompt: "Say hello to every player who joins", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-one-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(r.aiCalls.length, 1, "no repair call");
    assert.equal(r.repairs, 0);
    const kinds = r.autofixes.map((f: { kind: string }) => f.kind).sort();
    assert.deepEqual(kinds, ["main-final", "wrong-import"]);
    assert.equal(r.usage.savedRepairs, 1);
    const c = r.aiCalls[0];
    assert.deepEqual(c.tokens, { input: 32904, cacheRead: 28900, output: 3040, uncached: 4, cacheWrite: 4000 });
    assert.equal(c.turnsDetail.length, 2);
    assert.deepEqual(c.toolCalls, { Write: 3 });
    assert.equal(c.effort, "medium");
    for (const s of ["generate", "validate", "precheck", "compile", "autofix", "scan"]) assert.ok(r.usage.stages[s], `stage ${s}`);
    assert.equal(r.usage.stages.compile.n, 2, "compiled, auto-fixed, compiled again");
    assert.ok(r.dedupeKey);
    assert.ok(r.events.some((e: { message: string }) => /Fixed 1 known API mistake automatically/.test(e.message)));
    const calls = log();
    assert.deepEqual(calls[0].tools, ["Read", "Write", "Edit"], "fresh builds get the lean tool set");
    assert.equal(calls[0].effort, "medium");
    // the fixed source is what was kept
    const src = await (await fetch(`http://127.0.0.1:${port}/builds/pipe-one-01/source?path=src/main/java/dev/nxeon/plugins/hello/Hello.java`, { headers: { Authorization: `Bearer ${KEY}` } })).text();
    assert.match(src, /import org\.bukkit\.configuration\.file\.FileConfiguration;/);
    assert.match(src, /^public class Hello extends JavaPlugin/m);
  });

  it("reuses an identical earlier build with no AI call, and `fresh: true` opts out", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-two-02", prompt: "  Say hello to every player   who joins ", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-two-02");
    assert.equal(r.status, "succeeded");
    assert.equal(r.reusedFrom, "pipe-one-01");
    assert.equal(r.costUsd, 0);
    assert.equal(r.aiCalls.length, 0);
    assert.equal(r.jar.name, "Hello-1.0.0.jar");
    assert.equal(log().length, before, "the CLI was not called");
    await api("POST", "/builds", { id: "pipe-three-03", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", fresh: true });
    const f = await waitDone("pipe-three-03");
    assert.equal(f.status, "succeeded");
    assert.equal(f.reusedFrom, null);
    assert.equal(log().length, before + 1);
  });

  it("change requests keep Glob/Grep and are never reused", async () => {
    await api("POST", "/builds", { id: "pipe-four-04", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", baseBuildId: "pipe-one-01", changeRequest: "Say it twice" });
    const r = await waitDone("pipe-four-04");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(r.dedupeKey, null);
    const last = log().at(-1);
    assert.equal(last.kind, "change");
    assert.deepEqual(last.tools, ["Read", "Write", "Edit", "Glob", "Grep"]);
  });
});

