describe("modbuilder 0.5 pipeline (offline, fake CLI + javac)", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-pipe-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", FAKE_JAVAP]]) {
      fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    }
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/configuration/file/FileConfiguration.class\norg/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    port = 37000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_DEDUPE: "on",
        MB_EFFORT: "medium", FAKE_LOG: path.join(dir, "claude.log"),
      },
      stdio: ["ignore", "ignore", "pipe"],
    });
    let err = "";
    proc.stderr!.on("data", (d) => { err += d; });
    for (let i = 0; i < 100; i++) {
      try { const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json(); if (h.ok) return; } catch { /* starting */ }
      await new Promise((res) => setTimeout(res, 100));
    }
    throw new Error(`service did not start: ${err.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("reports 0.5 and its knobs on /health", async () => {
    const h = await (await fetch(`http://127.0.0.1:${port}/health`)).json();
    assert.equal(h.image, "0.5");
    assert.equal(h.features.usage, true);
    assert.equal(h.features.autofix, true);
    assert.equal(h.features.dedupe, true);
    assert.equal(h.features.effort, "medium");
  });

  it("builds with one AI call: wrong import + final main fixed without a model repair, usage recorded", async () => {
    await api("POST", "/builds", { id: "pipe-one-01", prompt: "Say hello to every player who joins", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-one-01");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(r.aiCalls.length, 1, "no repair call");
    assert.equal(r.repairs, 0);
    const kinds = r.autofixes.map((f: { kind: string }) => f.kind).sort();
    assert.deepEqual(kinds, ["main-final", "wrong-import"]);
    assert.equal(r.usage.savedRepairs, 1);
    const c = r.aiCalls[0];
    assert.deepEqual(c.tokens, { input: 32904, cacheRead: 28900, output: 3040, uncached: 4, cacheWrite: 4000 });
    assert.equal(c.turnsDetail.length, 2);
    assert.deepEqual(c.toolCalls, { Write: 3 });
    assert.equal(c.effort, "medium");
    for (const s of ["generate", "validate", "precheck", "compile", "autofix", "scan"]) assert.ok(r.usage.stages[s], `stage ${s}`);
    assert.equal(r.usage.stages.compile.n, 2, "compiled, auto-fixed, compiled again");
    assert.ok(r.dedupeKey);
    assert.ok(r.events.some((e: { message: string }) => /Fixed 1 known API mistake automatically/.test(e.message)));
    const calls = log();
    assert.deepEqual(calls[0].tools, ["Read", "Write", "Edit"], "fresh builds get the lean tool set");
    assert.equal(calls[0].effort, "medium");
    // the fixed source is what was kept
    const src = await (await fetch(`http://127.0.0.1:${port}/builds/pipe-one-01/source?path=src/main/java/dev/nxeon/plugins/hello/Hello.java`, { headers: { Authorization: `Bearer ${KEY}` } })).text();
    assert.match(src, /import org\.bukkit\.configuration\.file\.FileConfiguration;/);
    assert.match(src, /^public class Hello extends JavaPlugin/m);
  });

  it("reuses an identical earlier build with no AI call, and `fresh: true` opts out", async () => {
    const before = log().length;
    await api("POST", "/builds", { id: "pipe-two-02", prompt: "  Say hello to every player   who joins ", mcVersion: "1.21.11" });
    const r = await waitDone("pipe-two-02");
    assert.equal(r.status, "succeeded");
    assert.equal(r.reusedFrom, "pipe-one-01");
    assert.equal(r.costUsd, 0);
    assert.equal(r.aiCalls.length, 0);
    assert.equal(r.jar.name, "Hello-1.0.0.jar");
    assert.equal(log().length, before, "the CLI was not called");
    await api("POST", "/builds", { id: "pipe-three-03", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", fresh: true });
    const f = await waitDone("pipe-three-03");
    assert.equal(f.status, "succeeded");
    assert.equal(f.reusedFrom, null);
    assert.equal(log().length, before + 1);
  });

  it("change requests keep Glob/Grep and are never reused", async () => {
    await api("POST", "/builds", { id: "pipe-four-04", prompt: "Say hello to every player who joins", mcVersion: "1.21.11", baseBuildId: "pipe-one-01", changeRequest: "Say it twice" });
    const r = await waitDone("pipe-four-04");
    assert.equal(r.status, "succeeded", JSON.stringify(r.events));
    assert.equal(r.dedupeKey, null);
    const last = log().at(-1);
    assert.equal(last.kind, "change");
    assert.deepEqual(last.tools, ["Read", "Write", "Edit", "Glob", "Grep"]);
  });
});

